// ── Types ─────────────────────────────────────────────────────────────────────

type CampaignStatus = "draft" | "active" | "completed" | "paused";

type PhishingTemplate = {
  id: string;
  name: string;
  category: "credential-harvest" | "malware-delivery" | "whaling" | "spear-phishing" | "vishing" | "smishing";
  difficulty: "easy" | "medium" | "hard";
  subject: string;
  previewText: string;
  sender: string;
  successRate: number;
  tags: string[];
};

type Department = {
  name: string;
  headCount: number;
  sentCount: number;
  openRate: number;
  clickRate: number;
  reportRate: number;
  credentialRate: number;
  riskScore: number;
};

/** Matches the `phishing_campaigns` Supabase table columns exactly. */
type Campaign = {
  id: string;
  name: string;
  status: CampaignStatus;
  template_id: string;
  template_name: string;
  start_date: string;
  end_date: string;
  target_departments: string[];
  target_count: number;
  sent_count: number;
  open_count: number;
  click_count: number;
  report_count: number;
  credential_count: number;
  training_assigned: number;
  created_by: string;
  notes: string;
  created_at?: string;
  updated_at?: string;
};

type TrainingModule = {
  id: string;
  name: string;
  duration: string;
  assignedCount: number;
  completedCount: number;
  completionRate: number;
};

