// ── Helper Functions ──────────────────────────────────────────────────────────

function statusBadge(status: CampaignStatus) {
  const cfg: Record<CampaignStatus, { label: string; cls: string }> = {
    draft: { label: "Draft", cls: "bg-muted text-muted-foreground" },
    active: { label: "Active", cls: "bg-green-500/20 text-green-400" },
    completed: { label: "Completed", cls: "bg-purple-500/20 text-purple-400" },
    paused: { label: "Paused", cls: "bg-yellow-500/20 text-yellow-400" },
  };
  const { label, cls } = cfg[status] ?? cfg.draft;
  return <Badge className={`${cls} border-0 text-xs`}>{label}</Badge>;
}

function categoryBadge(cat: PhishingTemplate["category"]) {
  const cfg: Record<PhishingTemplate["category"], { label: string; cls: string }> = {
    "credential-harvest": { label: "Credential Harvest", cls: "bg-red-500/20 text-red-400" },
    "malware-delivery": { label: "Malware Delivery", cls: "bg-orange-500/20 text-orange-400" },
    "whaling": { label: "Whaling", cls: "bg-purple-500/20 text-purple-400" },
    "spear-phishing": { label: "Spear Phishing", cls: "bg-yellow-500/20 text-yellow-400" },
    "vishing": { label: "Vishing", cls: "bg-cyan-500/20 text-cyan-400" },
    "smishing": { label: "Smishing", cls: "bg-pink-500/20 text-pink-400" },
  };
  const { label, cls } = cfg[cat];
  return <Badge className={`${cls} border-0 text-xs`}>{label}</Badge>;
}

function difficultyBadge(d: PhishingTemplate["difficulty"]) {
  const cfg = {
    easy: "bg-green-500/20 text-green-400",
    medium: "bg-yellow-500/20 text-yellow-400",
    hard: "bg-red-500/20 text-red-400",
  };
  return <Badge className={`${cfg[d]} border-0 text-xs capitalize`}>{d}</Badge>;
}

function riskColor(score: number): string {
  if (score >= 75) return "text-red-400";
  if (score >= 50) return "text-orange-400";
  if (score >= 25) return "text-yellow-400";
  return "text-green-400";
}

function clickRateColor(rate: number): string {
  if (rate >= 30) return "text-red-400";
  if (rate >= 20) return "text-orange-400";
  if (rate >= 10) return "text-yellow-400";
  return "text-green-400";
}

